-- ============================================================
-- Final flashcard backfill: 42 new CONTENT concepts and 2,154 card mappings
--
-- Closes the flashcard side of the canonical concept layer. Every remaining
-- unmapped flashcard in the bank receives exactly one PRIMARY concept, except
-- two cards held deliberately as CARD_TOO_BROAD authoring repairs.
--
-- WHY 42 NEW OBJECTS IN A MAPPING PHASE. 31 of the 33 decks needed almost no new
-- vocabulary; 376 existing concepts absorbed 1,969 cards. Two chapters had no
-- curriculum layer at all: The Immune System and The Cardiovascular System each
-- carried one concept per question, 89 and 99 of them, every one with an empty
-- description and a name copied verbatim from its question's subtopic. Those are
-- a question index, not a vocabulary, so 34 of the 42 objects build the layer
-- both modalities were missing. All 34 carry at least one exact question
-- alignment, so none ships memory-only once the question side migrates.
--
-- CROSS-MODALITY. Existing concepts holding BOTH recall and application evidence
-- go from 34 to 364. That is the point of the programme: comparing what a student
-- remembers against what they can apply requires one stable id for both.
--
-- PROVENANCE. Every mapping is AI_PROPOSED in both mapping_status and source.
-- The ontology design was approved; 2,154 individual rows were not reviewed one
-- by one, and the provenance must not claim otherwise.
--
-- WRITE SCOPE. concepts, concept_sections, concept_disciplines,
-- concept_content_categories, flashcard_concepts. INSERT only. No UPDATE, no
-- DELETE, no TRUNCATE. No question mapping is touched: question_concepts must
-- read 2,659 before and after. No learner table is read or written.
--
-- WIDENING. 38 rows, all SECONDARY / is_primary = false. These tables carry
-- partial unique indexes on the primary flag, so a widening row written as
-- primary would be silently discarded by ON CONFLICT DO NOTHING.
--
-- DEFERRED, deliberately not here: the lipid mobilisation split, the
-- reducing-sugar merge, the Types of Reactions review, the Personality Disorder
-- Clusters review, and the immune and cardiovascular scenario-label cleanup.
-- Each is an UPDATE or DELETE and belongs to its own lifecycle migration.
-- ============================================================

BEGIN;

-- ────────────────────────────────────────────────────────────
-- 1. The 42 new CONTENT concepts.
-- ────────────────────────────────────────────────────────────
INSERT INTO public.concepts (slug, canonical_name, description, object_type, status, concept_level)
VALUES
  ('ABO_RH_BLOOD_TYPES', 'ABO and Rh Blood Types', 'Codominant A and B alleles with recessive i, the rule that plasma carries antibodies against absent antigens, Rh sensitisation requiring prior exposure, and the universal donor and recipient types.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('ACTIVE_PASSIVE_IMMUNITY', 'Active and Passive Immunity', 'Immunity from the host''s own adaptive response versus transferred ready-made antibody, and the consequences for memory and duration.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('AMINO_ACID_RECOGNITION_ABBREVIATIONS', 'Amino Acid Recognition and Abbreviations', 'The twenty standard amino acids by name, three-letter and one-letter abbreviation, and recognition of each side-chain structure.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('ANTIGENS_EPITOPES', 'Antigens and Epitopes', 'What makes a molecule antigenic, the epitope as the bound subregion, and how epitope size and accessibility set response diversity and cross-reactivity.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('AUTOIMMUNE_DISEASE', 'Autoimmune Disease', 'Disease produced when an intact immune response is directed at a self antigen, illustrated by demyelination in multiple sclerosis.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('B_CELL_ACTIVATION_ANTIBODY_DIVERSITY', 'B Cell Activation and Antibody Diversity', 'Activation of a naive B cell into plasma and memory cells, and the generation and refinement of antibody diversity by recombination, class switching and somatic hypermutation.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('BAROREFLEX_AUTONOMIC_CARDIOVASCULAR_CONTROL', 'Baroreflex and Autonomic Cardiovascular Control', 'Arterial baroreceptors in the carotid sinus and aortic arch, and the sympathetic, parasympathetic and adrenal limbs that adjust rate, contractility and resistance.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('BLOOD_COMPOSITION_PLASMA_FORMED_ELEMENTS', 'Blood Composition: Plasma and Formed Elements', 'Blood as a transport medium, the plasma and formed-element fractions, plasma water and its dissolved proteins, and the liver as their source.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('BLOOD_PRESSURE_MEASUREMENT', 'Blood Pressure and Its Measurement', 'Systolic and diastolic pressure, typical adult values, mean arterial pressure and pulse pressure, and how cuff measurement obtains them.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('BLOOD_VESSEL_STRUCTURE_TYPES', 'Blood Vessel Structure and Types', 'Arteries, veins and capillaries distinguished by direction and wall architecture: the endothelial lining, the tunica media as the thickest arterial layer, arterioles as resistance vessels, and veins as valved capacitance vessels.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('CAPILLARY_STRUCTURE_EXCHANGE', 'Capillary Structure and Exchange', 'The single endothelial layer on its basement membrane, capillary wall types, and exchange by diffusion of solutes versus bulk flow of fluid.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('CARDIAC_CONDUCTION_PACEMAKER_HIERARCHY', 'Cardiac Conduction and Pacemaker Hierarchy', 'The impulse pathway from SA node through AV node, bundle of His and Purkinje fibres, the AV delay, and the inherent rates that make lower sites escape pacemakers.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('CARDIAC_OUTPUT_STROKE_VOLUME', 'Cardiac Output and Stroke Volume', 'Cardiac output as heart rate times stroke volume, ejection fraction, contractility, and the requirement that the two ventricles eject equal volumes.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('CLONAL_SELECTION_IMMUNOLOGIC_MEMORY', 'Clonal Selection and Immunologic Memory', 'Antigen selecting a preexisting matching lymphocyte, clonal expansion, and the faster stronger secondary response carried by memory cells.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('CYTOKINES_INTERFERONS', 'Cytokines and Interferons', 'Secreted signalling proteins that coordinate immune responses, and the interferon response by which virally altered cells induce resistance in neighbours.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('ERYTHROCYTES_STRUCTURE_LIFECYCLE_TURNOVER', 'Erythrocytes: Structure, Lifecycle and Turnover', 'The biconcave anucleate erythrocyte, hematocrit, marrow production and the roughly 120-day lifespan ending in splenic and hepatic macrophage recycling of iron.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('HEART_CHAMBERS_VALVES', 'Heart Chambers and Valves', 'The four chambers as receiving atria and pumping ventricles, the interventricular septum, and the identity, location and cusp count of the atrioventricular and semilunar valves.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('HEMODYNAMICS_RESISTANCE_FLOW_VELOCITY', 'Hemodynamics: Resistance, Flow and Velocity', 'Pressure equals flow times resistance, the fourth-power dependence on radius, arterioles as the dominant resistance site, and why velocity is lowest where total cross-sectional area is greatest.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('HEMOSTASIS_COAGULATION_FIBRINOLYSIS', 'Hemostasis, Coagulation and Fibrinolysis', 'Exposure of collagen and tissue factor, the platelet plug of primary hemostasis, the cascade converting prothrombin to thrombin and fibrinogen to fibrin, and plasmin-mediated clot breakdown.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('HYPERSENSITIVITY_ALLERGY', 'Hypersensitivity and Allergy', 'Type I immediate hypersensitivity through IgE-coated mast cells and degranulation, and delayed cell-mediated hypersensitivity.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('INNATE_ADAPTIVE_IMMUNITY', 'Innate versus Adaptive Immunity', 'The two arms of the immune response contrasted by speed, specificity and the formation of lasting memory.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('LEUKOCYTE_LINEAGES_LYMPHOID_ORGANS', 'Leukocyte Lineages and Lymphoid Organs', 'Haematopoietic origin of all leukocytes, the primary lymphoid organs where lymphocytes mature, and the secondary lymphoid organs where they meet antigen.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('LEUKOCYTES_PLATELETS_BLOOD', 'Leukocytes and Platelets in Blood', 'Marrow origin of leukocytes and their immune role, the differential count, and platelets as megakaryocyte fragments.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('MHC_ANTIGEN_PRESENTATION', 'MHC and Antigen Presentation', 'Professional antigen-presenting cells, and MHC class I and II differing in peptide source, restriction to CD8 or CD4 T cells, and tissue distribution.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('NATURAL_KILLER_CELLS', 'Natural Killer Cells', 'Innate lymphocytes that induce apoptosis in virus-infected and tumour cells detected by loss of MHC class I, the missing-self mechanism.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('PATTERN_RECOGNITION_ACUTE_INFLAMMATION', 'Pattern Recognition and Acute Inflammation', 'Pattern recognition receptors detecting conserved pathogen and damage signals, and the vascular changes producing the cardinal signs of inflammation.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('PHAGOCYTES_GRANULOCYTES', 'Phagocytes and Granulocytes', 'The innate cellular effectors: phagocytosis and lysosomal killing, macrophages, neutrophils, dendritic cells, eosinophils, mast cells and basophils, and the granulocyte/agranulocyte division.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('POLYPROTIC_ACIDS_STEPWISE_DISSOCIATION', 'Polyprotic Acids and Stepwise Dissociation', 'Acids bearing more than one ionisable proton, their stepwise dissociation constants, and the species that dominates at each stage of titration.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('PORTAL_CIRCULATIONS', 'Portal Circulations', 'A portal system as two capillary beds in series, and the hepatic, hypophyseal and renal examples with what each one accomplishes.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('PROTEIN_STRUCTURE_DETERMINATION', 'Protein Structure Determination', 'Experimental determination of protein three-dimensional structure by X-ray crystallography, NMR and cryo-electron microscopy, and what each technique can resolve.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('PULMONARY_SYSTEMIC_CIRCUITS', 'Pulmonary and Systemic Circuits', 'The two circuits in series, the pulmonary vessels that invert the usual oxygenation rule, and why the left ventricle is the thicker pump.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('RENIN_ANGIOTENSIN_ALDOSTERONE_SYSTEM', 'Renin-Angiotensin-Aldosterone System', 'The cascade from juxtaglomerular renin release on falling blood pressure, through angiotensin-converting enzyme in the lung, to adrenal aldosterone secretion and sodium reabsorption.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('STARLING_FORCES_CAPILLARY_FLUID_BALANCE', 'Starling Forces and Capillary Fluid Balance', 'Hydrostatic and colloid osmotic pressure across the capillary wall, filtration at the arteriolar end and reabsorption at the venular end, and the plasma proteins that set oncotic pressure.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('SURFACE_BARRIERS_INFECTION', 'Surface Barriers to Infection', 'Physical and chemical barriers at body surfaces: keratinised skin, lysozyme, mucus, gastric acid, defensins and competition from resident flora.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('T_CELL_SUBSETS_EFFECTOR_FUNCTION', 'T Cell Subsets and Effector Function', 'Helper, cytotoxic, regulatory and memory T cells distinguished by co-receptor, MHC restriction and effector output.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('CARDIAC_CYCLE_HEART_SOUNDS', 'The Cardiac Cycle and Heart Sounds', 'Systole and diastole, the pressure relationships that open and close each valve, and the heart sounds those closures produce.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('COMPLEMENT_SYSTEM', 'The Complement System', 'Plasma protein cascade that opsonises, recruits phagocytes and assembles the membrane attack complex causing osmotic lysis, with host regulatory protection.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('LYMPHATIC_SYSTEM', 'The Lymphatic System', 'Return of excess interstitial fluid as lymph, lacteal absorption of dietary fat, drainage through nodes and the thoracic duct, and the consequence of blocked drainage.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('THYMIC_SELECTION_SELF_TOLERANCE', 'Thymic Selection and Self-Tolerance', 'Positive and negative selection in the thymus, and how escape of self-reactive lymphocytes breaks self-tolerance.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('URINARY_TRACT_MICTURITION', 'Urinary Tract and Micturition', 'The path of urine beyond the nephron: ureteric peristalsis, the bladder detrusor, the internal smooth and external skeletal urethral sphincters, and the spinal micturition reflex.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('VACCINATION', 'Vaccination', 'Live-attenuated, inactivated and subunit vaccines generating memory without disease, and conjugation to recruit T-dependent help.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT'),
  ('VENOUS_RETURN_PRELOAD', 'Venous Return and Preload', 'The peripheral determinants of blood returning to the heart: the skeletal-muscle pump acting through one-way venous valves, venoconstriction mobilising the venous reservoir, and the resulting effect on ventricular filling and preload.', 'CONTENT', 'ACTIVE_SEED', 'CONCEPT')
ON CONFLICT (slug) DO NOTHING;

-- All 42 must exist. Anything else means a slug collided and a concept is missing.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.concepts WHERE slug IN ('ABO_RH_BLOOD_TYPES', 'ACTIVE_PASSIVE_IMMUNITY', 'AMINO_ACID_RECOGNITION_ABBREVIATIONS', 'ANTIGENS_EPITOPES', 'AUTOIMMUNE_DISEASE', 'B_CELL_ACTIVATION_ANTIBODY_DIVERSITY', 'BAROREFLEX_AUTONOMIC_CARDIOVASCULAR_CONTROL', 'BLOOD_COMPOSITION_PLASMA_FORMED_ELEMENTS', 'BLOOD_PRESSURE_MEASUREMENT', 'BLOOD_VESSEL_STRUCTURE_TYPES', 'CAPILLARY_STRUCTURE_EXCHANGE', 'CARDIAC_CONDUCTION_PACEMAKER_HIERARCHY', 'CARDIAC_OUTPUT_STROKE_VOLUME', 'CLONAL_SELECTION_IMMUNOLOGIC_MEMORY', 'CYTOKINES_INTERFERONS', 'ERYTHROCYTES_STRUCTURE_LIFECYCLE_TURNOVER', 'HEART_CHAMBERS_VALVES', 'HEMODYNAMICS_RESISTANCE_FLOW_VELOCITY', 'HEMOSTASIS_COAGULATION_FIBRINOLYSIS', 'HYPERSENSITIVITY_ALLERGY', 'INNATE_ADAPTIVE_IMMUNITY', 'LEUKOCYTE_LINEAGES_LYMPHOID_ORGANS', 'LEUKOCYTES_PLATELETS_BLOOD', 'MHC_ANTIGEN_PRESENTATION', 'NATURAL_KILLER_CELLS', 'PATTERN_RECOGNITION_ACUTE_INFLAMMATION', 'PHAGOCYTES_GRANULOCYTES', 'POLYPROTIC_ACIDS_STEPWISE_DISSOCIATION', 'PORTAL_CIRCULATIONS', 'PROTEIN_STRUCTURE_DETERMINATION', 'PULMONARY_SYSTEMIC_CIRCUITS', 'RENIN_ANGIOTENSIN_ALDOSTERONE_SYSTEM', 'STARLING_FORCES_CAPILLARY_FLUID_BALANCE', 'SURFACE_BARRIERS_INFECTION', 'T_CELL_SUBSETS_EFFECTOR_FUNCTION', 'CARDIAC_CYCLE_HEART_SOUNDS', 'COMPLEMENT_SYSTEM', 'LYMPHATIC_SYSTEM', 'THYMIC_SELECTION_SELF_TOLERANCE', 'URINARY_TRACT_MICTURITION', 'VACCINATION', 'VENOUS_RETURN_PRELOAD');
  IF n <> 42 THEN RAISE EXCEPTION 'expected 42 new concepts, found %', n; END IF;
END $$;

