-- The widening must have landed. A partial unique index on the primary flag will
-- silently swallow these rows if they are ever written as primary.
DO $$
DECLARE d int; s int;
BEGIN
  SELECT count(*) INTO d FROM public.concept_disciplines cd JOIN public.concepts c ON c.id=cd.concept_id
    WHERE cd.role='SECONDARY' AND (c.slug, cd.discipline_code) IN (('ABSOLUTE_CONFIGURATION_CIP_RS_FISCHER','BIOCHEMISTRY'), ('CELL_CYCLE_PHASES_INTERPHASE','BIOCHEMISTRY'), ('COLLIGATIVE_PROPERTIES','BIOCHEMISTRY'), ('COOPERATIVITY_T_R_STATES_SIGMOIDAL_KINETICS','BIOLOGY'), ('CYTOSKELETON_INTERMEDIATE_FILAMENTS','BIOCHEMISTRY'), ('CYTOSKELETON_MICROFILAMENTS','BIOCHEMISTRY'), ('CYTOSKELETON_MICROTUBULES','BIOCHEMISTRY'), ('DENSITY_AND_SPECIFIC_GRAVITY','GENERAL_CHEMISTRY'), ('DIFFERENTIATION_STEM_CELL_POTENCY','BIOCHEMISTRY'), ('ENERGY_BALANCE_APPETITE','BIOLOGY'), ('HORMONE_CLASSES_CHEMISTRY','BIOCHEMISTRY'), ('HORMONE_TRANSPORT_SPECIFICITY_KINETICS','BIOCHEMISTRY'), ('IMMUNOGLOBULINS','BIOLOGY'), ('ISOELECTRIC_FOCUSING','GENERAL_CHEMISTRY'), ('LIPID_DIGESTION_BILE','BIOLOGY'), ('LOSS_CELL_CYCLE_CONTROL_CANCER','BIOCHEMISTRY'), ('MENDEL_S_LAWS_EPIGENETICS','BIOCHEMISTRY'), ('MOLECULAR_ORBITAL_THEORY','GENERAL_CHEMISTRY'), ('MUTATIONS','BIOCHEMISTRY'), ('OXYGEN_BINDING_PROTEINS','BIOLOGY'), ('POST_TRANSLATIONAL_PROCESSING_TARGETING','BIOLOGY'), ('PROTEIN_DIGESTION','BIOLOGY'), ('RESTING_MEMBRANE_POTENTIAL','BIOCHEMISTRY'), ('REVERSE_TRANSCRIPTION_CDNA','BIOLOGY'), ('TELOMERES_TELOMERASE','BIOLOGY'), ('TISSUES_CONNECTIVE_TISSUE','BIOCHEMISTRY'), ('TISSUE_SPECIFIC_METABOLISM','BIOLOGY'), ('UREA_CYCLE_METABOLIC_INTEGRATION','BIOLOGY'));
  IF d <> 28 THEN RAISE EXCEPTION 'expected 28 discipline widening rows, found %', d; END IF;
  SELECT count(*) INTO s FROM public.concept_sections cs JOIN public.concepts c ON c.id=cs.concept_id
    WHERE cs.is_primary = false AND (c.slug, cs.section_code) IN (('ABSOLUTE_CONFIGURATION_CIP_RS_FISCHER','BIO_BIOCHEM'), ('BICARBONATE_BUFFER_BLOOD_PH_PHYSIOLOGY','BIO_BIOCHEM'), ('CEREBRAL_CORTEX_ORGANIZATION','BIO_BIOCHEM'), ('COLLIGATIVE_PROPERTIES','BIO_BIOCHEM'), ('HINDBRAIN_STRUCTURES','BIO_BIOCHEM'), ('INCLUSIVE_FITNESS_AND_EVOLUTIONARY_GAME_THEORY','BIO_BIOCHEM'), ('LIMBIC_SYSTEM','BIO_BIOCHEM'), ('NEUROTRANSMITTER_CLASSES_AND_FUNCTIONS','BIO_BIOCHEM'), ('SYMPATHETIC_AND_PARASYMPATHETIC_FUNCTION','BIO_BIOCHEM'), ('TERATOGENS_AND_PRENATAL_DEVELOPMENT','BIO_BIOCHEM'));
  IF s <> 10 THEN RAISE EXCEPTION 'expected 10 section widening rows, found %', s; END IF;
END $$;

